NOM-01.code:
@layer components {
  .feed-page {
    padding-block: var(--shelf-space-lg);
    padding-inline: var(--shelf-space-md);
  }

  .feed-page-wrapper {
    max-width: 960px;
    width: 100%;
  }

  .feed-page-heading {
    font-size: var(--shelf-text-xl);
    font-weight: var(--shelf-weight-bold);
    color: var(--shelf-color-text-primary);
    margin-block-end: var(--shelf-space-lg);
  }

  .feed-list {
    display: flex;
    flex-direction: column;
    gap: var(--shelf-space-md);
  }

  .feed-item {
    background-color: var(--shelf-color-surface);
    border-radius: var(--shelf-radius-md);
    padding: var(--shelf-space-md);
    box-shadow: var(--shelf-shadow-sm);
  }

  .feed-item-title {
    font-size: var(--shelf-text-md);
    font-weight: var(--shelf-weight-semibold);
    color: var(--shelf-color-text-primary);
    margin-block-end: var(--shelf-space-xs);
  }

  .feed-item-description {
    font-size: var(--shelf-text-sm);
    color: var(--shelf-color-text-secondary);
  }
}

NOM-02.code:
@layer components {
  .project-grid {
    --shelf-project-grid-min-col: 16rem;
    --shelf-project-grid-gap: var(--shelf-space-4);
    --shelf-project-grid-padding: var(--shelf-space-4);

    list-style: none;
    padding: var(--shelf-project-grid-padding);
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(var(--shelf-project-grid-min-col), 1fr));
    gap: var(--shelf-project-grid-gap);
  }

  .project-card {
    --shelf-project-card-bg: var(--shelf-color-surface);
    --shelf-project-card-radius: var(--shelf-radius-md);
    --shelf-project-card-padding: var(--shelf-space-4);
    --shelf-project-card-gap: var(--shelf-space-2);
    --shelf-project-card-border: var(--shelf-color-border);

    background: var(--shelf-project-card-bg);
    border-radius: var(--shelf-project-card-radius);
    border: 1px solid var(--shelf-project-card-border);
    padding: var(--shelf-project-card-padding);
    display: flex;
    flex-direction: column;
    gap: var(--shelf-project-card-gap);
  }

  .project-name {
    color: var(--shelf-color-text-primary);
    font-size: var(--shelf-font-size-md);
    font-weight: var(--shelf-font-weight-semibold);
  }

  .project-description {
    color: var(--shelf-color-text-secondary);
    font-size: var(--shelf-font-size-sm);
  }
}

NOM-C1.code:
@layer components {
  .card-footer {
    display: flex;
    flex-direction: row;
    align-items: center;
    gap: var(--shelf-space-xs);
    padding-block-start: var(--shelf-space-sm);
    border-top: var(--shelf-borderWidth-thin) solid var(--shelf-borderColor-subtle);
  }

  .card-footer-timestamp {
    font-size: var(--shelf-font-size-xs);
    color: var(--shelf-fgColor-muted);
    font-family: var(--shelf-font-family-base);
    font-weight: var(--shelf-font-weight-regular);
  }

  .card-footer-action {
    margin-inline-start: auto;
    font-size: var(--shelf-font-size-xs);
    font-family: var(--shelf-font-family-base);
    font-weight: var(--shelf-font-weight-medium);
    color: var(--shelf-fgColor-accent);
    background: none;
    border: none;
    padding-block: var(--shelf-space-xs);
    padding-inline: var(--shelf-space-sm);
    border-radius: var(--shelf-radius-md);
    cursor: pointer;
    transition-property: background-color, color;
    transition-duration: var(--shelf-motion-duration-fast);
    transition-timing-function: var(--shelf-motion-easing-enter);
    outline-offset: var(--shelf-focusRing-offset);
  }

  .card-footer-action:hover {
    background-color: var(--shelf-bgColor-accent-hover);
    color: var(--shelf-fgColor-on-accent);
  }

  .card-footer-action:focus-visible {
    outline: var(--shelf-focusRing);
  }

  .card-footer-action:active {
    background-color: var(--shelf-bgColor-accent-active);
    color: var(--shelf-fgColor-on-accent);
  }

  .card-footer-action:disabled {
    color: var(--shelf-fgColor-muted);
    cursor: not-allowed;
  }
}
